## Code Example
```python
class TrieNode:
    def __init__(self):
        self.next = {}
        self.is_word = False

class Trie:
    def __init__(self):
        self.root = TrieNode()
    def insert(self, word):
        node = self.root
        for ch in word:
            if ch not in node.next:
                node.next[ch] = TrieNode()
            node = node.next[ch]
        node.is_word = True
    def _collect(self, node, prefix, res, limit):
        if len(res) >= limit:
            return
        if node.is_word:
            res.append(prefix)
        for ch in sorted(node.next.keys()):
            self._collect(node.next[ch], prefix + ch, res, limit)
    def autocomplete(self, prefix, limit):
        node = self.root
        for ch in prefix:
            if ch not in node.next:
                return []
            node = node.next[ch]
        res = []
        self._collect(node, prefix, res, limit)
        return res
    def startsWith(self, prefix):
        node = self.root
        for ch in prefix:
            if ch not in node.next:
                return False
            node = node.next[ch]
        return True
```

