## Why This Is Asked
This question tests combining shortest-path DP on DAGs with path counting and reconstruction, using a topological order. It also touches large-number handling and edge case ties.

## Key Concepts
- DAG dynamic programming, topological sort, shortest paths in DAGs, path counting, reconstruction.

## Code Example
```javascript
function countShortestPaths(n, edges, s, t) {
  const adj = Array.from({ length: n }, () => [])
  const indeg = Array(n).fill(0)
  for (const e of edges) { const {u,v,w} = e; adj[u].push([v,w]); indeg[v]++ }
  const q = []
  for (let i=0;i<n;i++) if (indeg[i]===0) q.push(i)
  const topo = []
  while (q.length) { const u = q.shift(); topo.push(u); for (const [v] of adj[u]) if (--indeg[v]===0) q.push(v) }
  const INF = Number.POSITIVE_INFINITY
  const dist = Array(n).fill(INF); dist[s]=0
  const cnt = Array(n).fill(0); cnt[s] = 1
  const par = Array(n).fill(-1)
  for (const u of topo) {
    for (const [v,w] of adj[u]) {
      const nd = dist[u] + w
      if (nd < dist[v]) { dist[v] = nd; cnt[v] = cnt[u]; par[v] = u }
      else if (nd === dist[v] && dist[u] !== INF) { cnt[v] += cnt[u]; if (par[v] === -1) par[v] = u }
    }
  }
  const path = []
  if (dist[t] !== INF) {
    for (let x = t; x !== -1; x = par[x]) path.push(x)
    path.reverse()
  }
  return { dist: dist[t], count: cnt[t], path }
}
```

